<template>
  <section>
    <div class="admin-section-head"><div><p class="eyebrow">Collections</p><h2>内容模块</h2></div></div>
    <div class="subtabs"><button v-for="tab in tabs" :key="tab.value" :class="{ active: active === tab.value }" @click="active = tab.value">{{ tab.label }}<span v-if="tab.value === 'guestbook' && pendingCount">{{ pendingCount }}</span></button></div>
    <AdminNotice :message="notice" :success="success" @close="notice = ''" />

    <section v-if="active === 'learning'" class="module-panel">
      <form class="inline-create" @submit.prevent="createLearning"><div class="field"><label>节点标题</label><input v-model="learningDraft.title" required /></div><div class="field grow"><label>说明</label><input v-model="learningDraft.description" /></div><div class="field"><label>状态</label><select v-model="learningDraft.status"><option value="locked">未来节点</option><option value="active">正在进行</option><option value="completed">已经点亮</option></select></div><button class="primary-button" :disabled="busyKey">{{ isBusy('create:learning') ? "添加中…" : "添加节点" }}</button></form>
      <div class="sortable-list">
        <article v-for="(item, index) in learning" :key="item.id" :class="{ editing: editingLearningId === item.id }">
          <span class="order">{{ index + 1 }}</span>
          <form v-if="editingLearningId === item.id" class="learning-edit-form" @submit.prevent="saveLearning(item, index)">
            <div class="field"><label>节点标题</label><input v-model="learningEditDraft.title" required /></div>
            <div class="field grow"><label>说明</label><textarea v-model="learningEditDraft.description" rows="3"></textarea></div>
            <div class="field"><label>状态</label><select v-model="learningEditDraft.status"><option value="locked">未来</option><option value="active">进行中</option><option value="completed">已点亮</option></select></div>
            <div class="field"><label>点亮时间</label><input v-model="learningEditDraft.lit_at" type="datetime-local" /></div>
            <div class="edit-actions"><button class="primary-button" :disabled="busyKey">{{ isBusy(`save:learning:${item.id}`) ? "保存中…" : "保存修改" }}</button><button type="button" class="secondary-button" :disabled="busyKey" @click="cancelLearningEdit">取消</button></div>
          </form>
          <template v-else>
            <div class="learning-summary"><strong>{{ item.title }}</strong><p v-if="item.description">{{ item.description }}</p><small>{{ learningStatusLabel(item.status) }}<template v-if="item.lit_at"> · {{ formatDate(item.lit_at) }}</template></small></div>
            <button type="button" :disabled="busyKey" @click="startLearningEdit(item)">编辑</button><button type="button" class="remove" :disabled="busyKey" @click="remove('learning', item)">{{ isBusy(`delete:learning:${item.id}`) ? "删除中…" : "删除" }}</button>
          </template>
        </article>
      </div>
    </section>

    <section v-else-if="active === 'library'" class="module-panel">
      <form class="card-form" @submit.prevent="createLibrary"><div class="form-grid three"><div class="field"><label>类型</label><select v-model="libraryDraft.item_type"><option value="book">书籍</option><option value="movie">电影</option><option value="anime">动漫</option></select></div><div class="field"><label>名称</label><input v-model="libraryDraft.title" required /></div><div class="field"><label>状态</label><select v-model="libraryDraft.status"><option value="wishlist">想看</option><option value="reading">进行中</option><option value="completed">已完成</option></select></div></div><div class="form-grid two"><div class="field"><label>豆瓣 / 外部链接</label><input v-model="libraryDraft.external_url" type="url" /></div><div class="field"><label>评分（0-10）</label><input v-model.number="libraryDraft.rating" type="number" min="0" max="10" step="0.5" /></div></div><div class="field"><label>简短感想</label><textarea v-model="libraryDraft.note" rows="3"></textarea></div><div class="image-row"><div class="field"><label>封面地址</label><input v-model="libraryDraft.cover_image" /></div><ImageUploader compact label="上传封面" @uploaded="libraryDraft.cover_image = $event.url" /></div><button class="primary-button" :disabled="busyKey">{{ isBusy('create:library') ? "添加中…" : "添加到图书馆" }}</button></form>
      <form class="library-filters" @submit.prevent="applyLibraryFilters">
        <div class="field filter-keyword"><label>搜索收藏</label><input v-model.trim="libraryFilterDraft.keyword" placeholder="输入名称或感想" /></div>
        <div class="field"><label>类型</label><select v-model="libraryFilterDraft.item_type"><option value="">全部类型</option><option value="book">书籍</option><option value="movie">电影</option><option value="anime">动漫</option></select></div>
        <div class="field"><label>状态</label><select v-model="libraryFilterDraft.status"><option value="">全部状态</option><option value="wishlist">想看</option><option value="reading">进行中</option><option value="completed">已完成</option></select></div>
        <button class="primary-button" :disabled="libraryLoading || busyKey">{{ libraryLoading ? "读取中…" : "筛选" }}</button><button class="secondary-button" type="button" :disabled="libraryLoading || busyKey" @click="resetLibraryFilters">重置</button>
        <span class="result-count">共 {{ libraryPagination.total }} 项</span>
      </form>
      <div v-if="libraryLoading" class="admin-empty">正在读取图书馆…</div>
      <div v-else-if="!library.length" class="admin-empty">没有找到符合条件的内容。</div>
      <div v-else class="collection-grid">
        <article v-for="item in library" :key="item.id" :class="{ editing: editingLibraryId === item.id }">
          <form v-if="editingLibraryId === item.id" class="library-edit-form" @submit.prevent="saveItem(item)">
            <div class="form-grid three"><div class="field"><label>类型</label><select v-model="libraryEditDraft.item_type"><option value="book">书籍</option><option value="movie">电影</option><option value="anime">动漫</option></select></div><div class="field"><label>名称</label><input v-model="libraryEditDraft.title" required /></div><div class="field"><label>状态</label><select v-model="libraryEditDraft.status"><option value="wishlist">想看</option><option value="reading">进行中</option><option value="completed">已完成</option></select></div></div>
            <div class="form-grid three"><div class="field"><label>评分（0-10）</label><input v-model.number="libraryEditDraft.rating" type="number" min="0" max="10" step="0.5" /></div><div class="field"><label>完成日期</label><input v-model="libraryEditDraft.finished_at" type="date" /></div><div class="field"><label>排序值</label><input v-model.number="libraryEditDraft.sort_order" type="number" /></div></div>
            <div class="field"><label>豆瓣 / 外部链接</label><input v-model="libraryEditDraft.external_url" type="url" /></div>
            <div class="field"><label>简短感想</label><textarea v-model="libraryEditDraft.note" rows="4"></textarea></div>
            <div class="image-row"><div class="field"><label>封面地址</label><input v-model="libraryEditDraft.cover_image" /></div><ImageUploader compact label="重新上传封面" @uploaded="libraryEditDraft.cover_image = $event.url" /></div>
            <div class="edit-actions"><button class="primary-button" :disabled="busyKey">{{ isBusy(`save:library:${item.id}`) ? "保存中…" : "保存修改" }}</button><button type="button" class="secondary-button" :disabled="busyKey" @click="cancelLibraryEdit">取消</button></div>
          </form>
          <template v-else>
            <img v-if="item.cover_image" :src="item.cover_image" :alt="item.title" />
            <div class="collection-summary"><small>{{ typeLabel(item.item_type) }} · {{ libraryStatusLabel(item.status) }}</small><strong>{{ item.title }}</strong><p v-if="item.note">{{ item.note }}</p><span v-if="item.rating !== null && item.rating !== undefined">{{ item.rating }}/10</span></div>
            <button type="button" :disabled="busyKey" @click="startLibraryEdit(item)">编辑</button><button type="button" class="remove" :disabled="busyKey" @click="remove('library', item)">{{ isBusy(`delete:library:${item.id}`) ? "删除中…" : "删除" }}</button>
          </template>
        </article>
      </div>
      <AdminPagination :page="libraryPagination.page" :total-pages="libraryPagination.totalPages" :loading="libraryLoading" label="图书馆分页" @change="loadLibrary" />
    </section>

    <section v-else-if="active === 'albums'" class="module-panel">
      <form class="inline-create" @submit.prevent="createAlbum"><div class="field"><label>相册名称</label><input v-model="albumDraft.title" required /></div><div class="field grow"><label>相册说明</label><input v-model="albumDraft.description" /></div><button class="primary-button" :disabled="busyKey">{{ isBusy('create:albums') ? "创建中…" : "创建相册" }}</button></form>
      <div class="album-admin-list"><article v-for="album in albums" :key="album.id"><div class="album-head"><div><h3>{{ album.title }}</h3><p>{{ album.description || "没有说明" }}</p></div><button class="danger-button" :disabled="busyKey" @click="remove('albums', album)">{{ isBusy(`delete:albums:${album.id}`) ? "删除中…" : "删除相册" }}</button></div><ImageUploader multiple compact label="向这个相册添加照片" @uploaded="addPhoto(album, $event)" /><div class="album-photos"><div v-for="photo in album.photos" :key="photo.id"><img :src="photo.thumbnail_url || photo.image_url" :alt="photo.caption || album.title" /><button :disabled="busyKey" @click="removePhoto(album, photo)">×</button></div></div></article></div>
    </section>

    <section v-else-if="active === 'guestbook'" class="module-panel">
      <div v-if="!messages.length" class="admin-empty">还没有留言。</div><div class="message-admin-list"><article v-for="message in messages" :key="message.id"><div class="message-head"><strong>{{ message.nickname }}</strong><time>{{ formatDate(message.created_at) }}</time><select v-model="message.status"><option value="pending">待审核</option><option value="approved">公开</option><option value="hidden">隐藏</option></select></div><p>{{ message.content }}</p><div class="field"><label>站长回复</label><textarea v-model="message.admin_reply" rows="2"></textarea></div><div class="item-actions"><button class="primary-button" :disabled="busyKey" @click="saveMessage(message)">{{ isBusy(`save:guestbook:${message.id}`) ? "保存中…" : "保存审核结果" }}</button><button class="danger-button" :disabled="busyKey" @click="remove('guestbook', message)">{{ isBusy(`delete:guestbook:${message.id}`) ? "删除中…" : "删除" }}</button></div></article></div>
    </section>

    <section v-else class="module-panel">
      <form class="card-form" @submit.prevent="createChangelog"><div class="form-grid three"><div class="field"><label>版本号</label><input v-model="changelogDraft.version" required placeholder="2.0.0" /></div><div class="field"><label>标题</label><input v-model="changelogDraft.title" required /></div><div class="field"><label>类型</label><select v-model="changelogDraft.change_type"><option value="feature">新增</option><option value="improvement">优化</option><option value="fix">修复</option></select></div></div><div class="field"><label>Markdown 内容</label><textarea v-model="changelogDraft.content" rows="8" required></textarea></div><div class="form-grid two"><div class="field"><label>状态</label><select v-model="changelogDraft.status"><option value="draft">草稿</option><option value="published">发布</option></select></div><div class="field"><label>发布时间</label><input v-model="changelogDraft.published_at" type="datetime-local" /></div></div><button class="primary-button" :disabled="busyKey">{{ isBusy('create:changelog') ? "创建中…" : "创建更新日志" }}</button></form>
      <div class="change-admin-list"><article v-for="entry in changelog" :key="entry.id"><div><small>{{ entry.status === "published" ? "已发布" : "草稿" }}</small><h3>v{{ entry.version }} · {{ entry.title }}</h3></div><select v-model="entry.status"><option value="draft">草稿</option><option value="published">发布</option></select><button :disabled="busyKey" @click="saveChangelog(entry)">{{ isBusy(`save:changelog:${entry.id}`) ? "保存中…" : "保存" }}</button><button class="remove" :disabled="busyKey" @click="remove('changelog', entry)">{{ isBusy(`delete:changelog:${entry.id}`) ? "删除中…" : "删除" }}</button></article></div>
    </section>
  </section>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from "vue";
import AdminNotice from "./AdminNotice.vue";
import AdminPagination from "./AdminPagination.vue";
import ImageUploader from "../ImageUploader.vue";
import { addAlbumPhoto, createAdminResource, deleteAdminResource, deleteAlbumPhoto, getAdminLibrary, getAdminResource, updateAdminResource } from "../../api/content";
const tabs = [{ value: "learning", label: "成长树" }, { value: "library", label: "图书馆" }, { value: "albums", label: "相册" }, { value: "guestbook", label: "留言审核" }, { value: "changelog", label: "更新日志" }];
const active = ref("learning"); const learning = ref([]); const library = ref([]); const albums = ref([]); const messages = ref([]); const changelog = ref([]); const notice = ref(""); const success = ref(false);
const editingLearningId = ref(null); const editingLibraryId = ref(null);
const libraryLoading = ref(true);
const busyKey = ref("");
const learningDraft = reactive({ title: "", description: "", status: "locked", lit_at: null, sort_order: 0, parent_id: null }); const libraryDraft = reactive({ item_type: "book", title: "", cover_image: "", external_url: "", status: "completed", rating: null, note: "", finished_at: null, sort_order: 0 }); const albumDraft = reactive({ title: "", description: "", cover_image: "", sort_order: 0 }); const changelogDraft = reactive({ version: "2.0.0", title: "", content: "", change_type: "feature", status: "draft", published_at: "" });
const learningEditDraft = reactive({ title: "", description: "", status: "locked", lit_at: "" });
const libraryEditDraft = reactive({ item_type: "book", title: "", cover_image: "", external_url: "", status: "completed", rating: null, note: "", finished_at: "", sort_order: 0 });
const libraryFilterDraft = reactive({ keyword: "", item_type: "", status: "" });
const libraryFilters = reactive({ keyword: "", item_type: "", status: "" });
const libraryPagination = reactive({ page: 1, pageSize: 12, total: 0, totalPages: 0 });
const pendingCount = computed(() => messages.value.filter((item) => item.status === "pending").length);
function toLocal(value) { if (!value) return ""; const date = new Date(value); return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16); }
function typeLabel(value) { return ({ book: "书籍", movie: "电影", anime: "动漫" })[value]; }
function learningStatusLabel(value) { return ({ locked: "未来节点", active: "正在进行", completed: "已经点亮" })[value] || value; }
function libraryStatusLabel(value) { return ({ wishlist: "想看", reading: "进行中", completed: "已完成" })[value] || value; }
function formatDate(value) { return new Date(value).toLocaleString("zh-CN"); }
function isBusy(key) { return busyKey.value === key; }
async function runAction(key, action, fallbackMessage) { if (busyKey.value) return null; busyKey.value = key; notice.value = ""; try { return await action(); } catch (error) { success.value = false; notice.value = error.response?.data?.detail || fallbackMessage; return null; } finally { busyKey.value = ""; } }
async function createLearning() { const payload = { ...learningDraft, sort_order: learning.value.length, lit_at: learningDraft.status === "completed" ? new Date().toISOString() : null }; const data = await runAction("create:learning", async () => (await createAdminResource("learning", payload)).data, "成长节点添加失败。"); if (!data) return; data.lit_at = toLocal(data.lit_at); learning.value.push(data); Object.assign(learningDraft, { title: "", description: "", status: "locked", lit_at: null, parent_id: null }); success.value = true; notice.value = "成长节点已添加。"; }
function startLearningEdit(item) { editingLearningId.value = item.id; Object.assign(learningEditDraft, { title: item.title, description: item.description || "", status: item.status, lit_at: item.lit_at || "" }); }
function cancelLearningEdit() { editingLearningId.value = null; }
async function saveLearning(item, index) { const saved = await save("learning", item, { ...learningEditDraft, description: learningEditDraft.description || null, sort_order: index, lit_at: learningEditDraft.lit_at ? new Date(learningEditDraft.lit_at).toISOString() : null }); if (saved) editingLearningId.value = null; }
async function loadLibrary(page = 1) { libraryLoading.value = true; try { const { data } = await getAdminLibrary({ page, page_size: libraryPagination.pageSize, keyword: libraryFilters.keyword || undefined, item_type: libraryFilters.item_type || undefined, status: libraryFilters.status || undefined }); if (!data.items.length && data.total > 0 && page > data.total_pages) { await loadLibrary(data.total_pages); return; } library.value = data.items; Object.assign(libraryPagination, { page: data.page, pageSize: data.page_size, total: data.total, totalPages: data.total_pages }); } catch (error) { library.value = []; success.value = false; notice.value = error.response?.data?.detail || "图书馆加载失败。"; } finally { libraryLoading.value = false; } }
function applyLibraryFilters() { Object.assign(libraryFilters, libraryFilterDraft); editingLibraryId.value = null; loadLibrary(1); }
function resetLibraryFilters() { Object.assign(libraryFilterDraft, { keyword: "", item_type: "", status: "" }); Object.assign(libraryFilters, libraryFilterDraft); editingLibraryId.value = null; loadLibrary(1); }
async function createLibrary() { const itemType = libraryDraft.item_type; const created = await runAction("create:library", async () => (await createAdminResource("library", { ...libraryDraft, rating: libraryDraft.rating === "" ? null : libraryDraft.rating, cover_image: libraryDraft.cover_image || null, external_url: libraryDraft.external_url || null, note: libraryDraft.note || null })).data, "创建失败。"); if (!created) return; Object.assign(libraryDraft, { item_type: "book", title: "", cover_image: "", external_url: "", status: "completed", rating: null, note: "", finished_at: null, sort_order: 0 }); Object.assign(libraryFilterDraft, { keyword: "", item_type: itemType, status: "" }); Object.assign(libraryFilters, libraryFilterDraft); success.value = true; notice.value = "内容已添加到图书馆。"; await loadLibrary(1); }
function startLibraryEdit(item) { editingLibraryId.value = item.id; Object.assign(libraryEditDraft, { item_type: item.item_type, title: item.title, cover_image: item.cover_image || "", external_url: item.external_url || "", status: item.status, rating: item.rating, note: item.note || "", finished_at: item.finished_at || "", sort_order: item.sort_order || 0 }); }
function cancelLibraryEdit() { editingLibraryId.value = null; }
async function saveItem(item) { const saved = await save("library", item, { ...libraryEditDraft, cover_image: libraryEditDraft.cover_image || null, external_url: libraryEditDraft.external_url || null, rating: libraryEditDraft.rating === "" ? null : libraryEditDraft.rating, note: libraryEditDraft.note || null, finished_at: libraryEditDraft.finished_at || null }); if (saved) { editingLibraryId.value = null; await loadLibrary(libraryPagination.page); } }
async function createAlbum() { const data = await runAction("create:albums", async () => (await createAdminResource("albums", albumDraft)).data, "相册创建失败。"); if (!data) return; albums.value.unshift(data); Object.assign(albumDraft, { title: "", description: "", cover_image: "", sort_order: 0 }); success.value = true; notice.value = "相册已创建。"; }
async function addPhoto(album, asset) { try { const { data } = await addAlbumPhoto(album.id, { media_id: asset.id, image_url: asset.url, thumbnail_url: asset.thumbnail_url, caption: "", sort_order: album.photos.length }); album.photos.push(data); if (!album.cover_image) { album.cover_image = asset.thumbnail_url || asset.url; await updateAdminResource("albums", album.id, { cover_image: album.cover_image }); } success.value = true; notice.value = "照片已加入相册。"; } catch (error) { success.value = false; notice.value = error.response?.data?.detail || "照片加入相册失败。"; } }
async function removePhoto(album, photo) { const removed = await runAction(`photo:delete:${photo.id}`, async () => { await deleteAlbumPhoto(photo.id); return true; }, "照片删除失败。"); if (!removed) return; album.photos = album.photos.filter((item) => item.id !== photo.id); success.value = true; notice.value = "照片已删除。"; }
async function saveMessage(item) { await save("guestbook", item, { status: item.status, admin_reply: item.admin_reply || null }); }
async function createChangelog() { const payload = { ...changelogDraft, published_at: changelogDraft.published_at ? new Date(changelogDraft.published_at).toISOString() : (changelogDraft.status === "published" ? new Date().toISOString() : null) }; const data = await runAction("create:changelog", async () => (await createAdminResource("changelog", payload)).data, "更新日志创建失败。"); if (!data) return; changelog.value.unshift(data); Object.assign(changelogDraft, { version: "2.0.0", title: "", content: "", change_type: "feature", status: "draft", published_at: "" }); success.value = true; notice.value = "更新日志已创建。"; }
async function saveChangelog(item) { await save("changelog", item, { status: item.status, published_at: item.status === "published" ? (item.published_at || new Date().toISOString()) : item.published_at }); }
async function save(resource, item, payload) { const data = await runAction(`save:${resource}:${item.id}`, async () => (await updateAdminResource(resource, item.id, payload)).data, "保存失败。"); if (!data) return false; Object.assign(item, data); if (resource === "learning") item.lit_at = toLocal(item.lit_at); success.value = true; notice.value = "内容已保存。"; return true; }
async function remove(resource, item) { if (!window.confirm("确定删除这条内容？")) return; const removed = await runAction(`delete:${resource}:${item.id}`, async () => { await deleteAdminResource(resource, item.id); return true; }, "删除失败。"); if (!removed) return; if (resource === "library") { const targetPage = library.value.length === 1 && libraryPagination.page > 1 ? libraryPagination.page - 1 : libraryPagination.page; editingLibraryId.value = null; await loadLibrary(targetPage); } else { const map = { learning, albums, guestbook: messages, changelog }; map[resource].value = map[resource].value.filter((entry) => entry.id !== item.id); } success.value = true; notice.value = "内容已删除。"; }
onMounted(async () => { const resources = ["learning", "albums", "guestbook", "changelog"]; const results = await Promise.allSettled([...resources.map(getAdminResource), loadLibrary()]); const refs = [learning, albums, messages, changelog]; results.slice(0, resources.length).forEach((result, index) => { if (result.status === "fulfilled") refs[index].value = result.value.data; }); learning.value.forEach((item) => { item.lit_at = toLocal(item.lit_at); }); });
</script>

